mapper.update:
UPDATE ai_session SET status = #{newStatus}, version = version + 1
WHERE id = #{id} AND tenant_id = #{tenantId}
  AND status = #{oldStatus} AND version = #{version}

UPDATE ai_session SET status = 'RUNNING', node_id = #{nodeId},
    cli_session_ref = #{cliSessionRef}, version = version + 1
WHERE id = #{id} AND tenant_id = #{tenantId}
  AND status = 'QUEUED' AND version = #{version}

UPDATE ai_session SET result_json = #{resultJson}, status = #{newStatus},
    version = version + 1
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version}

mapper.select:
SELECT * FROM ai_session
WHERE status IN
#{s}
  AND gmt_modified < DATE_SUB(NOW(3), INTERVAL #{beforeMs} / 1000 SECOND)
  AND is_deleted = 0
LIMIT #{limit}
